CREATE OR REPLACE FUNCTION public.accept_loan_offer(p_offer_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_offer public.loan_offers%rowtype;
    v_request public.loan_requests%rowtype;
    v_wallet public.wallets%rowtype;
    v_borrower public.profiles%rowtype;
    v_lender public.profiles%rowtype;
    v_amount bigint;
    v_interest bigint;
    v_total bigint;
    v_loan_id uuid;
begin
    if auth.uid() is null then raise exception 'Sign in first' using errcode = '28000'; end if;
    perform 1 from public.loan_requests where id = (select loan_request_id from public.loan_offers where id = p_offer_id) for update;
    select * into v_offer from public.loan_offers where id = p_offer_id and status = 'OFFERED' for update;
    if not found then raise exception 'Offer is no longer available'; end if;
    select * into v_request from public.loan_requests where id = v_offer.loan_request_id for update;
    if v_request.borrower_id <> auth.uid() then raise exception 'Only the borrower can accept this offer'; end if;
    -- All money movements lock participant profiles and wallets in UUID order.
    perform 1 from public.profiles where id in (v_request.borrower_id,v_offer.lender_id) order by id for update;
    perform 1 from public.wallets where user_id = v_request.borrower_id or user_id in (
        select lender_id from public.loan_offers where loan_request_id = v_request.id
            and status in ('OFFERED', 'TERMS_REQUESTED')
    ) order by user_id for update;
    if v_request.status not in ('REQUESTED', 'PARTIALLY_FUNDED') or v_request.remaining_amount <= 0 then raise exception 'Request is closed'; end if;
    if v_request.expires_at <= now() then raise exception 'Request expired'; end if;
    v_amount := least(v_offer.amount, v_request.remaining_amount);
    select * into v_borrower from public.profiles where id = v_request.borrower_id for update;
    if v_borrower.borrowing_frozen then raise exception 'Borrowing is frozen'; end if;
    if v_borrower.available_limit < v_amount and not (v_offer.above_limit_override and
        v_request.direct_request_to = v_offer.lender_id and v_request.above_limit_requested) then
        raise exception 'Borrowing limit exceeded; designated lender approval is required';
    end if;
    select * into v_wallet from public.wallets where user_id = v_offer.lender_id for update;
    if not found or v_wallet.locked_balance < v_offer.amount or v_wallet.balance < v_amount then raise exception 'Reserved funds unavailable'; end if;
    select * into v_lender from public.profiles where id = v_offer.lender_id for update;
    v_interest := round(v_amount * v_offer.interest_rate * v_offer.repayment_period_days / 36500.0)::bigint;
    v_total := v_amount + v_interest;
    insert into public.loans (loan_request_id, borrower_id, lender_id, principal, interest_rate, interest_amount,
        total_repayment, due_date, above_limit_override)
    values (v_request.id, v_request.borrower_id, v_offer.lender_id, v_amount, v_offer.interest_rate,
        v_interest, v_total, now() + make_interval(days => v_offer.repayment_period_days), v_offer.above_limit_override)
    returning id into v_loan_id;
    update public.wallets set balance = balance - v_amount, locked_balance = locked_balance - v_offer.amount, updated_at = now()
     where user_id = v_offer.lender_id;
    update public.wallets set balance = balance + v_amount, updated_at = now() where user_id = v_request.borrower_id;
    update public.loan_offers set status = 'ACCEPTED' where id = p_offer_id;
    update public.loan_requests set funded_amount = funded_amount + v_amount, remaining_amount = remaining_amount - v_amount,
        status = case when remaining_amount - v_amount = 0 then 'FULLY_FUNDED' else 'PARTIALLY_FUNDED' end where id = v_request.id;
    -- The request lock serializes acceptance, submission, terms and cancellation.
    -- Release only these offers, preserving reservations on other requests.
    update public.wallets w set locked_balance = w.locked_balance - reserved.amount, updated_at = now()
        from (
            select lender_id, sum(amount) as amount from public.loan_offers
            where loan_request_id = v_request.id and id <> p_offer_id
                and status in ('OFFERED', 'TERMS_REQUESTED')
            group by lender_id
        ) reserved
        where w.user_id = reserved.lender_id;
    with closed as (
        update public.loan_offers set status = 'DECLINED',
            requested_interest_rate = null, requested_repayment_period_days = null
        where loan_request_id = v_request.id and id <> p_offer_id
            and status in ('OFFERED', 'TERMS_REQUESTED')
        returning id, lender_id, amount
    )
    insert into public.notifications (user_id, type, title, message, related_entity_id)
        select lender_id, 'LOAN_OFFER_DECLINED', 'Offer automatically closed',
            format('%s already accepted an offer from another person. Your KSh %s offer has been closed and its reserved funds are now available in your wallet.',
                v_borrower.full_name, amount), id
        from closed;
    insert into public.transactions (type, sender_id, recipient_id, amount, loan_id, description)
    values ('LOAN_FUNDED', v_offer.lender_id, v_request.borrower_id, v_amount, v_loan_id, format('KSh %s funded to %s', v_amount, v_borrower.full_name));
    insert into public.notifications (user_id, type, title, message, related_entity_id) values
        (v_request.borrower_id, 'LOAN_ACCEPTED', 'Support accepted', format('KSh %s was funded by %s.', v_amount, v_lender.full_name), v_loan_id),
        (v_offer.lender_id, 'LOAN_ACCEPTED', 'Offer accepted', format('%s accepted your KSh %s offer.', v_borrower.full_name, v_amount), v_loan_id);
    update public.profiles set available_limit = greatest(0, available_limit - v_amount) where id = v_request.borrower_id;
    perform public.record_trust_event(v_offer.lender_id, 'COMMUNITY_SUPPORT', 1, format('Supported %s with KSh %s.', v_borrower.full_name, v_amount), v_loan_id);
    perform public.refresh_profile_limit(v_request.borrower_id);
    return v_loan_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_loan_offer_reviewed(p_offer_id uuid, p_expected_amount bigint, p_expected_interest_rate numeric, p_expected_period_days integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.loan_offers%rowtype;
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 perform 1 from public.loan_requests where id=(select loan_request_id from public.loan_offers where id=p_offer_id) and borrower_id=auth.uid() for update;
 if not found then raise exception 'Offer unavailable'; end if;
 select * into o from public.loan_offers where id=p_offer_id and status='OFFERED' for update;
 if not found or o.amount is distinct from p_expected_amount or o.interest_rate is distinct from p_expected_interest_rate
 or o.repayment_period_days is distinct from p_expected_period_days then raise exception 'Offer terms changed; refresh and review the updated offer'; end if;
 return public.accept_loan_offer(p_offer_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_daily_trust_penalties(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d date; first_day date; last_day date; loan_id uuid; before_limit integer; after_limit integer;
begin
    perform 1 from public.profiles where id=p_user_id for update;
    insert into public.kash_trust_state(user_id,cycle_peak,clean_cycle)
    select id,trust_score,trust_score=0 from public.profiles where id=p_user_id on conflict do nothing;
    select greatest(min((l.due_date at time zone 'Africa/Nairobi')::date+1),
        (s.policy_started_at at time zone 'Africa/Nairobi')::date)
    into first_day from public.loans l cross join public.kash_trust_state s
    where l.borrower_id=p_user_id and s.user_id=p_user_id
        and l.status not in ('REPAID','RECOVERED_EXTERNALLY') and l.due_date<now()
    group by s.policy_started_at;
    last_day := (now() at time zone 'Africa/Nairobi')::date;
    if first_day is null or first_day>last_day then return; end if;
    -- Do not rescan an entire old debt on every five-minute Cron invocation.
    first_day := greatest(first_day,(select max(penalty_date)+1
        from public.kash_trust_daily_penalties where user_id=p_user_id));
    if first_day>last_day then return; end if;
    for d in select generate_series(first_day::timestamp,last_day::timestamp,interval '1 day')::date loop
        select id into loan_id from public.loans where borrower_id=p_user_id
            and status not in ('REPAID','RECOVERED_EXTERNALLY')
            and (due_date at time zone 'Africa/Nairobi')::date<d order by due_date,id limit 1;
        if loan_id is null then continue; end if;
        select borrowing_limit into before_limit from public.profiles where id=p_user_id;
        insert into public.kash_trust_daily_penalties(user_id,penalty_date,related_loan_id,limit_before,limit_after)
        values(p_user_id,d,loan_id,before_limit,before_limit) on conflict do nothing;
        if not found then continue; end if;
        perform public.record_trust_event(p_user_id,'DAILY_DELAY',-10,
            format('Payment delayed on %s; daily limit reduction approximately 0.288194%%.',d),loan_id);
        select borrowing_limit into after_limit from public.profiles where id=p_user_id;
        update public.kash_trust_daily_penalties set limit_after=after_limit
        where user_id=p_user_id and penalty_date=d;
    end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_loan_offer(p_offer_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.loan_offers%rowtype; r public.loan_requests%rowtype;
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 select * into r from public.loan_requests where id=(select loan_request_id from public.loan_offers where id=p_offer_id) for update;
 select * into o from public.loan_offers where id=p_offer_id and lender_id=auth.uid() and status in ('OFFERED','TERMS_REQUESTED') for update;
 if not found then raise exception 'Offer unavailable'; end if;
 perform 1 from public.wallets where user_id=auth.uid() for update;
 update public.wallets set locked_balance=locked_balance-o.amount,updated_at=now() where user_id=auth.uid();
 -- Clear obsolete action notifications. Keep the cancellation notification independent of deleted offer.
 delete from public.notifications where related_entity_id=o.id and type in ('LOAN_OFFER','LOAN_OFFER_UPDATED','LOAN_OFFER_TERMS_REQUESTED');
 delete from public.loan_offers where id=o.id;
 insert into public.notifications(user_id,type,title,message,related_entity_id) values
 (r.borrower_id,'LOAN_OFFER_CANCELLED','Offer cancelled',format('Your lender cancelled the KSh %s offer. It is no longer available.',o.amount),null);
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_loan_request(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null then raise exception 'Sign in first'; end if;
    perform 1 from public.loan_requests where id = p_request_id and borrower_id = auth.uid()
        and status = 'REQUESTED' and funded_amount = 0 for update;
    if not found then raise exception 'Request cannot be cancelled after support begins'; end if;
    perform public.release_request_offers(p_request_id);
    update public.loan_requests set status = 'CANCELLED' where id = p_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_member_profile(p_full_name text, p_username text, p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 if p_full_name is null or length(trim(p_full_name))=0 or p_username is null
 or lower(trim(p_username)) !~ '^[a-z0-9_]{3,24}$' or lower(trim(p_username)) ~ '^user_[a-f0-9]{19}$'
 or p_email is null or trim(p_email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Complete full name, username and email'; end if;
 update public.profiles set full_name=trim(p_full_name),username=lower(trim(p_username)),profile_email=lower(trim(p_email)) where id=auth.uid();
 if not found then raise exception 'Profile unavailable'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_member_profile(p_full_name text, p_username text, p_email text, p_phone text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_phone text; v_existing text;
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 v_phone:=public.canonical_member_phone(p_phone);
 if v_phone is null then raise exception 'Enter a valid Kenyan mobile number'; end if;
 if p_full_name is null or length(trim(p_full_name))=0 or p_username is null
 or lower(trim(p_username)) !~ '^[a-z0-9_]{3,24}$'
 or lower(trim(p_username)) ~ '^user_[a-f0-9]{19}$'
 or p_email is null or trim(p_email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
 then raise exception 'Complete full name, username, email and phone number'; end if;
 select phone into v_existing from public.profiles where id=auth.uid() for update;
 if not found then raise exception 'Profile unavailable'; end if;
 if nullif(trim(v_existing),'') is not null
 and public.canonical_member_phone(v_existing) is distinct from v_phone
 then raise exception 'Phone changes require account verification'; end if;
 update public.profiles set full_name=trim(p_full_name),username=lower(trim(p_username)),
 profile_email=lower(trim(p_email)),
 phone=case when nullif(trim(v_existing),'') is null then v_phone else v_existing end
 where id=auth.uid();
end;
$function$

CREATE OR REPLACE FUNCTION public.create_loan_offer(p_request_id uuid, p_amount bigint, p_interest_rate numeric, p_period_days integer, p_approve_above_limit boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_request public.loan_requests%rowtype;
    v_wallet public.wallets%rowtype;
    v_id uuid;
    v_total bigint;
    v_max_interest numeric;
begin
    if auth.uid() is null then raise exception 'Sign in first' using errcode = '28000'; end if;
    select * into v_request from public.loan_requests where id = p_request_id for update;
    if not found or v_request.status not in ('REQUESTED', 'PARTIALLY_FUNDED') or v_request.expires_at <= now() then
        raise exception 'Request is no longer available';
    end if;
    if v_request.direct_request_to is not null and v_request.direct_request_to <> auth.uid() then
        raise exception 'This request is private';
    end if;
    if v_request.direct_request_to is null and not exists (
        select 1 from public.connections c where c.status = 'ACCEPTED'
            and ((c.requester_id = auth.uid() and c.recipient_id = v_request.borrower_id)
                or (c.recipient_id = auth.uid() and c.requester_id = v_request.borrower_id))
    ) then
        raise exception 'Connect with this borrower first';
    end if;
    if v_request.borrower_id = auth.uid() or p_amount <= 0 or p_amount > v_request.remaining_amount then
        raise exception 'Invalid offer amount';
    end if;
    if v_request.above_limit_requested and v_request.direct_request_to is distinct from auth.uid() then
        raise exception 'Above-limit requests are direct only';
    end if;
    if v_request.above_limit_requested and not p_approve_above_limit then
        raise exception 'Lender must explicitly approve this above-limit request';
    end if;
    if p_approve_above_limit and
        (not v_request.above_limit_requested or v_request.direct_request_to is distinct from auth.uid()) then
        raise exception 'Only the designated lender may approve an above-limit request';
    end if;
    v_max_interest := case when v_request.above_limit_requested then 15 else 7 end;
    if p_interest_rate is null or p_interest_rate <> trunc(p_interest_rate)
        or p_period_days is null or p_interest_rate not between 0 and v_max_interest
        or p_period_days not between 7 and v_request.preferred_period_days then
        raise exception 'Interest exceeds the limit for this request or the repayment period is invalid';
    end if;

    select * into v_wallet from public.wallets where user_id = auth.uid() for update;
    if not found or v_wallet.balance - v_wallet.locked_balance < p_amount then
        raise exception 'Insufficient available wallet balance';
    end if;
    if exists (
        select 1 from public.lender_preferences lp
        where lp.user_id = auth.uid() and lp.maximum_lending_amount > 0 and p_amount > lp.maximum_lending_amount
    ) then raise exception 'Offer exceeds your maximum lending amount'; end if;

    v_total := p_amount + round(p_amount * p_interest_rate * p_period_days / 36500.0)::bigint;
    update public.wallets set locked_balance = locked_balance + p_amount, updated_at = now()
        where user_id = auth.uid();
    insert into public.loan_offers (
        loan_request_id, lender_id, amount, interest_rate, repayment_period_days, total_repayment, above_limit_override
    ) values (
        p_request_id, auth.uid(), p_amount, p_interest_rate, p_period_days, v_total, p_approve_above_limit
    ) returning id into v_id;
    insert into public.notifications (user_id, type, title, message, related_entity_id)
    values (v_request.borrower_id, 'LOAN_OFFER', 'New support offer',
        format('A supporter offered KSh %s at %s%% for %s days%s.', p_amount, p_interest_rate, p_period_days,
            case when v_request.above_limit_requested then ' and approved your disclosed above-limit request' else '' end),
        v_id);
    return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_loan_request(p_amount bigint, p_purpose text, p_description text, p_period_days integer, p_direct_request_to uuid DEFAULT NULL::uuid, p_above_limit_requested boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_profile public.profiles%rowtype;
    v_id uuid;
    v_connection record;
begin
    if auth.uid() is null then raise exception 'Sign in first' using errcode = '28000'; end if;
    select * into v_profile from public.profiles where id = auth.uid() for update;
    if not found or v_profile.borrowing_frozen then raise exception 'Borrowing is unavailable'; end if;
    if p_amount <= 0 or p_period_days not between 7 and 365 then raise exception 'Invalid request terms'; end if;
    if length(trim(p_purpose)) = 0 or length(trim(p_description)) = 0 then
        raise exception 'Purpose and description are required';
    end if;
    if p_direct_request_to = auth.uid() then raise exception 'Cannot request support from yourself'; end if;
    if p_direct_request_to is not null and not exists (
        select 1 from public.connections c where c.status = 'ACCEPTED'
            and ((c.requester_id = auth.uid() and c.recipient_id = p_direct_request_to)
                or (c.recipient_id = auth.uid() and c.requester_id = p_direct_request_to))
    ) then
        raise exception 'Direct requests are available only to connected members';
    end if;
    if p_above_limit_requested <> (p_amount > v_profile.available_limit) then
        raise exception 'Above-limit disclosure must match the requested amount';
    end if;
    if p_amount > v_profile.available_limit and p_direct_request_to is null then
        raise exception 'Above-limit requests must be directed to a connected lender';
    end if;

    insert into public.loan_requests (
        borrower_id, requested_amount, funded_amount, remaining_amount, purpose, description,
        preferred_period_days, direct_request_to, above_limit_requested
    ) values (auth.uid(), p_amount, 0, p_amount, trim(p_purpose), trim(p_description),
        p_period_days, p_direct_request_to, p_above_limit_requested) returning id into v_id;
    if p_direct_request_to is not null then
        insert into public.notifications (user_id, type, title, message, related_entity_id)
        values (p_direct_request_to, 'DIRECT_REQUEST', 'Direct support request',
            case when p_above_limit_requested then
                format('%s requested KSh %s for %s, exceeding their available borrowing limit by KSh %s.',
                    v_profile.full_name, p_amount, trim(p_purpose), p_amount - v_profile.available_limit)
            else format('%s requested KSh %s for %s.', v_profile.full_name, p_amount, trim(p_purpose))
            end,
            v_id);
    else
        for v_connection in
            select case when requester_id = auth.uid() then recipient_id else requester_id end as other_user
            from public.connections where status = 'ACCEPTED'
                and (requester_id = auth.uid() or recipient_id = auth.uid())
        loop
            insert into public.notifications (user_id, type, title, message, related_entity_id)
            values (v_connection.other_user, 'NEW_LOAN_REQUEST', 'Community request',
                format('%s requested KSh %s for %s.', v_profile.full_name, p_amount, trim(p_purpose)), v_id);
        end loop;
    end if;
    return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.decline_loan_offer(p_offer_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_offer public.loan_offers%rowtype;
begin
    if auth.uid() is null then raise exception 'Sign in first' using errcode = '28000'; end if;
    perform 1 from public.loan_requests where id = (select loan_request_id from public.loan_offers where id = p_offer_id) for update;
    select * into v_offer from public.loan_offers where id = p_offer_id and borrower_id = auth.uid() and status in ('OFFERED', 'TERMS_REQUESTED') for update;
    if not found then raise exception 'Offer is no longer available'; end if;
    update public.loan_offers set status = 'DECLINED' where id = p_offer_id;
    update public.wallets set locked_balance = greatest(0, locked_balance - v_offer.amount), updated_at = now() where user_id = v_offer.lender_id;
    insert into public.notifications (user_id, type, title, message, related_entity_id)
    values (v_offer.lender_id, 'LOAN_OFFER_DECLINED', 'Offer declined', format('%s declined your support offer.',(select full_name from public.profiles where id=auth.uid())), p_offer_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.derive_offer_borrower()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    select borrower_id into new.borrower_id from public.loan_requests where id = new.loan_request_id;
    if new.borrower_id is null or new.borrower_id = new.lender_id then raise exception 'Invalid offer participants'; end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.edit_loan_offer(p_offer_id uuid, p_amount bigint, p_interest_rate numeric, p_period_days integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.loan_offers%rowtype; r public.loan_requests%rowtype; w public.wallets%rowtype;
begin
 if auth.uid() is null then raise exception 'Sign in first'; end if;
 select * into r from public.loan_requests where id=(select loan_request_id from public.loan_offers where id=p_offer_id) for update;
 select * into o from public.loan_offers where id=p_offer_id and lender_id=auth.uid() and status='OFFERED' for update;
 if not found or r.status not in ('REQUESTED','PARTIALLY_FUNDED') or r.expires_at<=now() then raise exception 'Offer unavailable'; end if;
 if p_amount is null or p_amount<=0 or p_amount>r.remaining_amount or p_interest_rate is null
 or p_interest_rate<>trunc(p_interest_rate) or p_interest_rate not between 0 and (case when r.above_limit_requested then 15 else 7 end)
 or p_period_days is null or p_period_days not between 7 and r.preferred_period_days then raise exception 'Invalid offer terms'; end if;
 if exists(select 1 from public.lender_preferences where user_id=auth.uid() and maximum_lending_amount>0 and maximum_lending_amount<p_amount) then raise exception 'Maximum lending amount exceeded'; end if;
 select * into w from public.wallets where user_id=auth.uid() for update;
 if not found or w.balance-w.locked_balance+o.amount<p_amount then raise exception 'Insufficient available wallet balance'; end if;
 update public.wallets set locked_balance=locked_balance-o.amount+p_amount,updated_at=now() where user_id=auth.uid();
 update public.loan_offers set amount=p_amount,interest_rate=p_interest_rate,repayment_period_days=p_period_days,
 total_repayment=p_amount+round(p_amount*p_interest_rate*p_period_days/36500.0)::bigint,
 requested_interest_rate=null,requested_repayment_period_days=null where id=o.id;
 insert into public.notifications(user_id,type,title,message,related_entity_id) values
 (r.borrower_id,'LOAN_OFFER_UPDATED','Offer updated',format('Your lender updated the offer to KSh %s at %s%% for %s days. Review the updated terms before accepting.',p_amount,p_interest_rate,p_period_days),o.id);
end;
